function addDays(y,m,d,n){ var dt=new Date(Date.UTC(y,m-1,d)); dt.setUTCDate(dt.getUTCDate()+n); return dt; }
function gestationalAge(lmpY,lmpM,lmpD, asOfY,asOfM,asOfD){
  lmpY=+lmpY;lmpM=+lmpM;lmpD=+lmpD; asOfY=+asOfY;asOfM=+asOfM;asOfD=+asOfD;
  if(!(lmpY>0)||!(lmpM>=1&&lmpM<=12)||!(lmpD>=1&&lmpD<=31)) return {error:'LMP 日期无效'};
  var lmp=Date.UTC(lmpY,lmpM-1,lmpD), asOf=Date.UTC(asOfY,asOfM-1,asOfD);
  if(asOf<lmp) return {error:'计算日期早于 LMP'};
  var days=Math.floor((asOf-lmp)/86400000);
  var weeks=Math.floor(days/7), rem=days%7;
  var trimester = weeks<14?'孕早期': weeks<28?'孕中期':'孕晚期';
  var edd=addDays(lmpY,lmpM,lmpD,280);
  var ez=('0'+(edd.getUTCMonth()+1)).slice(-2), ed=('0'+edd.getUTCDate()).slice(-2);
  return {weeks:weeks, days:rem, trimester:trimester, edd:edd.getUTCFullYear()+'-'+ez+'-'+ed, totalDays:days}; }
var EXPORTS={gestationalAge:gestationalAge, addDays:addDays};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PregnancyWeekForgePure = EXPORTS; }
